function compute(state) {
  var Q = state.Q, K = state.K, V = state.V;
  var dk = Q.length ? Q[0].length : 0, nk = K.length, dv = V.length ? V[0].length : 0;
  var scale = state.scaled ? 1 / Math.sqrt(Math.max(1, dk)) : 1;
  function dot(a, b) { var s = 0; for (var i = 0; i < a.length; i++) s += a[i] * b[i]; return s; }
  var raw = Q.map(function (q) { return K.map(function (k) { return dot(q, k); }); });
  var S = raw.map(function (r) { return r.map(function (x) { return x * scale; }); });
  var A = S.map(function (r) {
    var m = Math.max.apply(null, r);
    var e = r.map(function (x) { return Math.exp(x - m); });
    var z = e.reduce(function (a, b) { return a + b; }, 0);
    return e.map(function (x) { return x / z; });
  });
  var O = A.map(function (w) {
    var o = [];
    for (var j = 0; j < dv; j++) { var s = 0; for (var i = 0; i < nk; i++) s += w[i] * V[i][j]; o.push(s); }
    return o;
  });
  var rowErr = 0, outErr = 0;
  A.forEach(function (w, qi) {
    rowErr = Math.max(rowErr, Math.abs(w.reduce(function (a, b) { return a + b; }, 0) - 1));
    var acc = new Array(dv).fill(0);
    w.forEach(function (wi, i) { V[i].forEach(function (v, j) { acc[j] += wi * v; }); });
    acc.forEach(function (v, j) { outErr = Math.max(outErr, Math.abs(v - O[qi][j])); });
  });
  var maxW = A.length ? Math.max.apply(null, A[0]) : 0;
  return {
    values: { scale: scale, sqrt_dk: Math.sqrt(dk), row_sum_err: rowErr, out_err: outErr, max_w_q1: maxW },
    series: { w_q1: A[0] || [], s_q1: S[0] || [] },
    matrices: { raw: raw, S: S, A: A, O: O }
  };
}
